changeSet.sql:
CREATE TABLE auth_user (
    user_id uuid PRIMARY KEY,
    username varchar(64) NOT NULL UNIQUE,
    password_hash varchar(100) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE auth_refresh_family (
    family_id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES auth_user(user_id),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz
);
CREATE INDEX auth_refresh_family_user ON auth_refresh_family(user_id);
CREATE TABLE auth_refresh_token (
    token_hash varchar(64) PRIMARY KEY,
    family_id uuid NOT NULL REFERENCES auth_refresh_family(family_id),
    consumed_at timestamptz
);
CREATE INDEX auth_refresh_token_family ON auth_refresh_token(family_id);
CREATE TABLE auth_rate_limit (
    client_hash varchar(64) PRIMARY KEY,
    window_started_at timestamptz NOT NULL,
    attempts integer NOT NULL CHECK (attempts > 0)
);
